<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\UserMfaRecoveryCodeUserVO;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\UserMfaRecoveryCodeCodeHashVO;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\UserMfaRecoveryCodeUsedAtVO;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\UserMfaRecoveryCodeCreatedAtVO;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\UserMfaRecoveryCodeVersionVO;
use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\UserMfaRecoveryCodeAttributes;
use PHPUnit\Framework\TestCase;

final class UserMfaRecoveryCodeAttributesUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new UserMfaRecoveryCodeAttributes();
        $userOneValue = new UserRef('one');
        $userOtherValue = new UserRef('other');
        $copy = $value->user($userOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new UserRef('one'), $value->getUser());
        $this->assertNotEquals(new UserRef('other'), $value->getUser());
        $this->assertEquals(new UserRef('one'), $value->getUserOrCurrent(UserMfaRecoveryCodeUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('other'), $value->getUserOrCurrent(UserMfaRecoveryCodeUserVO::from($userOtherValue))->value());
        $value->unsetUser();
        $this->assertEquals(new UserRef('other'), $value->getUserOrCurrent(UserMfaRecoveryCodeUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('one'), $value->getUserOrCurrent(UserMfaRecoveryCodeUserVO::from($userOtherValue))->value());
        $codeHashOneValue = 'one';
        $codeHashOtherValue = 'other';
        $copy = $value->codeHash($codeHashOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getCodeHash());
        $this->assertNotEquals('other', $value->getCodeHash());
        $this->assertEquals('one', $value->getCodeHashOrCurrent(UserMfaRecoveryCodeCodeHashVO::from($codeHashOtherValue))->value());
        $this->assertNotEquals('other', $value->getCodeHashOrCurrent(UserMfaRecoveryCodeCodeHashVO::from($codeHashOtherValue))->value());
        $value->unsetCodeHash();
        $this->assertEquals('other', $value->getCodeHashOrCurrent(UserMfaRecoveryCodeCodeHashVO::from($codeHashOtherValue))->value());
        $this->assertNotEquals('one', $value->getCodeHashOrCurrent(UserMfaRecoveryCodeCodeHashVO::from($codeHashOtherValue))->value());
        $usedAtOneValue = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $usedAtOtherValue = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $copy = $value->usedAt($usedAtOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getUsedAt());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getUsedAt());
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getUsedAtOrCurrent(UserMfaRecoveryCodeUsedAtVO::from($usedAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getUsedAtOrCurrent(UserMfaRecoveryCodeUsedAtVO::from($usedAtOtherValue))->value());
        $value->unsetUsedAt();
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getUsedAtOrCurrent(UserMfaRecoveryCodeUsedAtVO::from($usedAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getUsedAtOrCurrent(UserMfaRecoveryCodeUsedAtVO::from($usedAtOtherValue))->value());
        $createdAtOneValue = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $createdAtOtherValue = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $copy = $value->createdAt($createdAtOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getCreatedAt());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getCreatedAt());
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getCreatedAtOrCurrent(UserMfaRecoveryCodeCreatedAtVO::from($createdAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getCreatedAtOrCurrent(UserMfaRecoveryCodeCreatedAtVO::from($createdAtOtherValue))->value());
        $value->unsetCreatedAt();
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getCreatedAtOrCurrent(UserMfaRecoveryCodeCreatedAtVO::from($createdAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getCreatedAtOrCurrent(UserMfaRecoveryCodeCreatedAtVO::from($createdAtOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(UserMfaRecoveryCodeVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(UserMfaRecoveryCodeVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(UserMfaRecoveryCodeVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(UserMfaRecoveryCodeVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
